// Full encyclopedia entries: Languedoc-Roussillon.
const LR_LAN = ["Cahier des charges AOC Languedoc, homologated by arrêté of 11 August 2026 (BO Agri)", "https://info.agriculture.gouv.fr/boagri/document_administratif-ec0fa131-4766-401d-9f09-aa0f942d6504/telechargement"];
const LR_MTP = ["Decanter: Languedoc's Montpeyroux gains cru status (March 2026)", "https://www.decanter.com/wine-news/languedocs-montpeyroux-gains-cru-status/"];
function lr(o) {
  const facts = [["Category", o.cat], ["Recognized", o.rec]].concat(o.facts || []);
  const sections = [["The place", `<p>${o.place}</p>`], ["The rules", `<p>${o.rules}</p>`]];
  if (o.history) sections.push(["History", `<p>${o.history}</p>`]);
  sections.push(["In the glass", `<p>${o.glass}</p>`]);
  if (o.exam) sections.push(["For the exam", `<p>${o.exam}</p>`]);
  return { lede: o.lede, facts, sections, producers: o.producers || [], sources: o.sources || [], checked: "2026-11-14" };
}

// ===== Languedoc =====
APXF["fr-languedoc"] = lr({ lede: "The regional appellation covering the Languedoc and Roussillon from Nîmes to the Spanish border, created in 2007 to replace Coteaux du Languedoc, with nine geographic names for its best villages.", cat: "AOC: red, rosé and white; nine geographic names", rec: "2007 (replacing Coteaux du Languedoc, 1985); current specification homologated 11 August 2026", facts: [["Red rules", "At least two grapes; Syrah and Mourvèdre together at least 20%; Grenache or Lledoner Pelut at least 20% when Carignan is used; Carignan and Cinsault 40% at most each; accessory grapes 20% at most"], ["White rules", "At least two principal grapes; Picpoul 50% at most; Viognier 10% at most; Muscat 5% at most"], ["Base yields", "Red 50 hl/ha (ceiling 60); rosé 54 (60); white 60 (70)"], ["Ripeness", "Red and rosé grapes at least 198 g/L sugar (11.5% natural alcohol)"], ["Geographic names", "Cabrières, La Méjanelle, Pézenas, Quatourze, Saint-Christol, Saint-Drézéry, Saint-Georges-d'Orques, Saint-Saturnin, Sommières"]], place: "The Languedoc is a vast amphitheater between the Mediterranean and the foothills of the Massif Central, the Montagne Noire and the Corbières, with garrigue scrub, a hot dry climate and the tramontane wind. Soils range from schist and limestone in the hills to gravel terraces and coastal sands.", rules: "A broad appellation for blends of southern grapes. It forms the base of a pyramid: regional (Languedoc), then sub-regional appellations (Corbières, Minervois, Saint-Chinian, Pic Saint-Loup, Terrasses du Larzac, Grès de Montpellier and others), then communal appellations covering no more than about ten communes (Faugères, Fitou, La Clape, Corbières-Boutenac, Minervois-La Livinière and, since 2026, Montpeyroux). The nine geographic names have lower yields, from 40 hectoliters per hectare at Saint-Drézéry to 45 at Pézenas and Sommières.", history: "The Languedoc was France's bulk-wine vineyard for most of the twentieth century, producing cheap Aramon and Carignan for industrial workers. Vine-pull schemes from the 1970s, replanting with Syrah, Grenache and Mourvèdre, and an influx of ambitious growers from the 1980s turned it into one of France's most dynamic regions.", glass: "Ripe, spicy reds with dark fruit and garrigue herbs; rosés and whites of growing quality.", producers: ["Mas de Daumas Gassac", "Domaine de la Grange des Pères", "Domaine d'Aupilhac", "Gérard Bertrand", "Domaine Peyre Rose", "Mas Jullien"], sources: [LR_LAN] });
function lan(name, o) { return lr({ lede: o.lede, cat: "AOC Languedoc with the geographic name " + name + ": " + o.colors, rec: "Geographic name of AOC Languedoc", facts: [["Communes", o.comm], ["Yield", o.y]], place: o.place, rules: "One of nine geographic names in the August 2026 Languedoc specification, with lower yields than the base appellation.", glass: o.glass, producers: o.producers || [], sources: [LR_LAN] }); }
