APXF["fr-montpeyroux"] = lr({ lede: "The Languedoc's newest communal cru, approved by INAO in February 2026 after some thirty years as a Languedoc geographic name: red wine from the foot of Mont Saint-Baudille.", cat: "AOC (communal cru), red only", rec: "Approved by INAO in February 2026; first vintage 2026, on sale from October 2027", facts: [["Area", "About 594 ha"], ["Communes", "Montpeyroux, Arboras, Lagamas, Saint-Jean-de-Fos"], ["Grapes", "Main: Carignan, Grenache, Mourvèdre, Syrah. Secondary: Cinsault, Counoise, Morrastel"], ["Blend", "At least three grapes"], ["Yield", "42 hl/ha"], ["Ageing", "At least one year"]], place: "Montpeyroux lies about 40 kilometers north-west of Montpellier at the foot of Mont Saint-Baudille, an enclave inside the Terrasses du Larzac. Cool air from the Larzac plateau gives large day-night temperature swings.", rules: "The new appellation is red only, requires at least three grapes, a maximum yield of 42 hectoliters per hectare and at least a year of ageing. It joins Faugères and La Livinière at the top tier of the Languedoc hierarchy. The decree still needed final formal steps, including European Commission sign-off, when the change was announced.", glass: "Fresh, structured reds with dark fruit, herbs and fine tannin.", producers: ["Domaine d'Aupilhac", "Domaine Alain Chabanon", "Domaine Villa Dondona", "Cave de l'Artisan (Montpeyroux)"], sources: [LR_MTP] });
APXF["fr-gres-de-montpellier"] = lr({ lede: "Red wine from the hills and terraces around Montpellier, a Languedoc geographic name since 2003 that became its own appellation from the 2024 vintage.", cat: "AOC, red only", rec: "Geographic name of Coteaux du Languedoc from 2003; own appellation approved by INAO on 30 November 2023 (first vintage 2024); specification homologated 18 November 2025", facts: [["Communes", "45 in the Hérault, from Montagnac to Lunel"], ["Area", "About 4,600 ha delimited, about 420 ha producing the appellation"], ["Grapes", "Principal: Grenache, Mourvèdre, Syrah (at least 60% of plantings, each 80% at most). Accessory: Carignan, Cinsault, Morrastel"], ["Base yield", "45 hl/ha (ceiling 49)"], ["Release", "Aged until 15 September and sold from 1 October of the year after harvest"]], place: "The area spans about 60 kilometers around Montpellier, on stony terraces, limestone and sandstone ('grès' refers to the stony soils), between the sea and the garrigue hills.", rules: "Red only, Grenache-Syrah-Mourvèdre-based, with about a year of ageing. It left the list of Languedoc geographic names when it became its own appellation.", glass: "Ripe, spicy reds with dark fruit and garrigue.", producers: ["Château de Flaugergues", "Domaine de la Prose"], sources: [LR_LAN, ["INAO, Grès de Montpellier specification (homologated 18 November 2025)", "https://extranet.inao.gouv.fr/fichier/PNO2025AOPGresdeMontpellier.pdf"], ["Decanter: Grés de Montpellier gains appellation status", "https://www.decanter.com/wine-news/languedocs-gres-de-montpellier-gains-appellation-status-519391"]] });
